-- US-020: the checkout's bounded settings (AC-S4, AC-S8): orders.sales_close_buffer_minutes and the
-- public API's Valkey rate limits (checkout.* per client IP / phone / landing page, captcha.* per
-- client IP). APP_SETTING_BOUNDS feeds app_settings_bounds_check; the new prefixes are whole positive
-- numbers like otp.* and orders.*. sql/seed.sql inserts the defaults after this migration.
ALTER TABLE "app_settings" DROP CONSTRAINT "app_settings_positive_int_check";--> statement-breakpoint
ALTER TABLE "app_settings" DROP CONSTRAINT "app_settings_bounds_check";--> statement-breakpoint
ALTER TABLE "app_settings" ADD CONSTRAINT "app_settings_positive_int_check" CHECK (("app_settings"."key" NOT LIKE 'otp.%' AND "app_settings"."key" NOT LIKE 'orders.%' AND "app_settings"."key" NOT LIKE 'checkout.%' AND "app_settings"."key" NOT LIKE 'captcha.%') OR (jsonb_typeof("app_settings"."value") = 'number' AND ("app_settings"."value" #>> '{}')::numeric > 0 AND ("app_settings"."value" #>> '{}')::numeric = trunc(("app_settings"."value" #>> '{}')::numeric)));--> statement-breakpoint
ALTER TABLE "app_settings" ADD CONSTRAINT "app_settings_bounds_check" CHECK (CASE WHEN "app_settings"."key" NOT IN ('otp.code_ttl_seconds', 'otp.max_attempts', 'otp.phone_cap', 'otp.phone_window_seconds', 'otp.ip_cap', 'otp.ip_window_seconds', 'otp.cooldown_seconds', 'orders.expiry_seconds', 'orders.sales_close_buffer_minutes', 'checkout.ip_cap', 'checkout.ip_window_seconds', 'checkout.phone_cap', 'checkout.phone_window_seconds', 'checkout.lp_cap', 'checkout.lp_window_seconds', 'captcha.ip_cap', 'captcha.ip_window_seconds') THEN true WHEN jsonb_typeof("app_settings"."value") <> 'number' THEN false ELSE CASE "app_settings"."key" WHEN 'otp.code_ttl_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 900 WHEN 'otp.max_attempts' THEN (value #>> '{}')::numeric BETWEEN 1 AND 5 WHEN 'otp.phone_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 10 WHEN 'otp.phone_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 3600 AND 86400 WHEN 'otp.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100 WHEN 'otp.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 600 AND 86400 WHEN 'otp.cooldown_seconds' THEN (value #>> '{}')::numeric BETWEEN 15 AND 600 WHEN 'orders.expiry_seconds' THEN (value #>> '{}')::numeric BETWEEN 900 AND 86400 WHEN 'orders.sales_close_buffer_minutes' THEN (value #>> '{}')::numeric BETWEEN 5 AND 1440 WHEN 'checkout.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 1000 WHEN 'checkout.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'checkout.phone_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100 WHEN 'checkout.phone_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'checkout.lp_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100000 WHEN 'checkout.lp_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'captcha.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 1000 WHEN 'captcha.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 END END);